Set $\bar\chi(\bar v)=\overline{\chi(v)}$ and let $GH_\partial$ denote the cohomology of $\partial$
   \begin{equation}\label{eq:ACK}
    GH_{\overline\partial}^{n-p}(\mathfrak g)\cong H^p(\mathfrak L,\mathbb C_\chi),\qquad
    GH_{\partial}^{-n+p}(\mathfrak g)
    \cong H^p(\overline\mathfrak L,\mathbb C_{\bar\chi}),
    \end{equation}
    If $\mathrm d\rho=c(z)\rho$, then
    \begin{equation}\label{eq:chi}
    \chi(v)=2\langle z,v\rangle\qquad(v\in\mathfrak L).
    \end{equation}
    In particular, $\chi=0$ if and only if the invariant generator
    $\rho$ is closed.

For every $\alpha\in\bigwedge^\bullet\mathfrak L^*$,
\begin{equation}\label{eq:almost-d}
\mathrm d_\mathfrak L\alpha=-\phi\wedge\Psi_C\alpha.
\end{equation}

\label{thm:diagonal-existence}
The Lie algebra $\mathfrak g_A$ admits an invariant generalized complex structure
of type $k$ if and only if, with multiplicities, the eigenvalues of
$A$ can be arranged as
\begin{equation}\label{eq:A-spectrum}
\operatorname{spec}(A)=\{\lambda_1,\lambda_1,\ldots,\lambda_h,\lambda_h,
\mu,\zeta_1,-\zeta_1,\ldots,\zeta_s,-\zeta_s\},
\qquad h+s=n-1,
\end{equation}
where $h,s\ge0$ and either $k=h$ or $k=h+1$.

\label{lem:model-integrability}
Both spinors in~\eqref{eq:models} are non-degenerate and integrable.
For the corresponding model,
\begin{equation}\label{eq:Lambda}
\mathrm d\rho=-\Lambda e^0\wedge\rho=c(-\Lambda e^0)\rho,\qquad
\Lambda_{\mathrm I}=\sum_{i=1}^h\lambda_i,
\qquad
\Lambda_{\mathrm {II}}=\mu+\sum_{i=1}^h\lambda_i.
\end{equation}

\label{lem:averaging}
The operator $\operatorname{Av}$ commutes with $\mathrm d$, maps $U^j(X)$ onto
$\mathfrak U^j$, and commutes with $\partial$ and $\overline\partial$. Consequently, putting
$Q^j=\ker(\operatorname{Av}|_{U^j(X)})$,
\begin{equation}\label{eq:averaging-splitting}
U^\bullet(X)=\mathfrak U^\bullet\oplus Q^\bullet
\end{equation}
is a decomposition into subcomplexes for both $\partial$ and $\overline\partial$, and
$\overline{Q^j}=Q^{-j}$.

\label{prop:spectral-sequences}
Assume that $\mathcal J$ is given by~\eqref{eq:bundle-spinor} and that
$\Gamma$ satisfies~\eqref{eq:lattice-hypotheses}. Consider the filtration
\begin{equation}\label{eq:filtration}
F^pC^m=\{f\in C^m:\ f(v_1,\ldots,v_m)=0\text{ whenever at least }
m-p+1\text{ arguments lie in }\mathfrak S\}
\end{equation}
of $C^\bullet(\mathfrak L,K)$, and its analogue on $C^\bullet(L_X,K_X)$ with
$\mathfrak S$ replaced by $S_X=\mathcal B\bigl(T(X/B)_\mathbb C\bigr)$. They
give first-quadrant spectral sequences
\begin{align}
E_2^{p,q}&=H^p\bigl(L_B,K_B\otimes\mathcal H^q\bigr)
\ \Longrightarrow\ H^{p+q}(L_X,K_X)\cong GH_{\overline\partial}^{n-p-q}(X),
\label{eq:global-SS}\\
\widetilde E_2^{p,q}&=H^p\bigl(\mathfrak L_B,K_{\mathfrak b}\otimes V^q\bigr)
\ \Longrightarrow\ H^{p+q}(\mathfrak L,K)\cong GH_{\overline\partial}^{n-p-q}(\mathfrak g_A).
\label{eq:invariant-SS}
\end{align}
Here $L_B$ acts on $K_B\otimes\mathcal H^q$ through the holomorphic
structures along $T^{0,1}B$, and $T^{*1,0}B$ acts trivially. The action
of $\mathfrak L_B$ on $K_{\mathfrak b}\otimes V^q$ is its invariant restriction.
The inclusion of invariant cochains is filtered and induces a morphism
$\widetilde E_r^{p,q}\to E_r^{p,q}$. Under the identifications
\begin{equation}\label{eq:second-pages}
E_2^{p,q}\cong\bigoplus_{\substack{0\le a,b\le k\\ a-b=k-p}}
H^b\bigl(B,\Omega^a_B\otimes\mathcal H^q\bigr),\qquad
\widetilde E_2^{p,q}\cong\bigoplus_{\substack{0\le a,b\le k\\ a-b=k-p}}
H^{a,b}_{\overline\partial}\bigl(\mathfrak b;V^q\bigr),
\end{equation}
the morphism at the second page is the direct sum of the comparison
maps~\eqref{eq:comparison-map} for $M=V^q$, composed with the
isomorphism of Lemma~\ref{lem:GM}.
